public class TwoPhaseCommitCoordinator {
    public void executeCommit(List<ResourceParticipant> participants) throws TransactionException {
        // Phase 1: Prepare
        boolean allPrepared = true;
        Map<ResourceParticipant, Vote> votes = new HashMap<>();

        for (ResourceParticipant participant : participants) {
            Vote vote = participant.prepare();
            votes.put(participant, vote);
            if (vote != Vote.VOTE_COMMIT) {
                allPrepared = false;
            }
        }

        // Write decision to durable log BEFORE sending commands
        if (allPrepared) {
            durableLog.write(TransactionState.GLOBAL_COMMIT);
            durableLog.force(); // Ensure disk sync

            // Phase 2: Commit (If coordinator crashes here, recovery reads log and retries)
            for (ResourceParticipant participant : participants) {
                participant.commit();
            }
        } else {
            durableLog.write(TransactionState.GLOBAL_ABORT);
            durableLog.force();
            for (ResourceParticipant participant : participants) {
                participant.rollback();
            }
        }
    }
}
